"""Diagonal Fisher Information Matrix estimation.

Appendix C.1::

    L_aux(theta) = sum_i F^i (theta_pre^i - theta^i)^2

where ``F`` is the diagonal of the Fisher Information Matrix.  For a policy we
use the *empirical* Fisher estimated with samples from the pre-training
distribution::

    F_i = E_{s ~ D, a ~ pi_*}[ (d log pi_*(a | s) / d theta_i)^2 ]

The NetHack experiments sample 10000 batches from the NLD-AA dataset to compute
the Fisher matrix (addendum), the Montezuma's Revenge experiments use batches
sampled with the pre-trained agent and the Meta-World experiments follow
Wolczyk et al. (2021).
"""

from __future__ import annotations

from typing import Callable, Dict, Iterable, Optional

import torch
import torch.nn as nn
from torch import Tensor


def _zero_like_params(params: Dict[str, nn.Parameter]) -> Dict[str, Tensor]:
    return {name: torch.zeros_like(p, device=p.device) for name, p in params.items()}


class DiagonalFisher:
    """Accumulate the diagonal empirical Fisher over a stream of batches.

    Parameters
    ----------
    module:
        The module whose parameters are tracked (usually the policy/actor).
    log_prob_fn:
        Callable mapping a batch ``(observations, **kwargs)`` to a tensor of
        shape ``(batch,)`` holding ``log pi_*(a | s)`` for actions sampled from
        ``pi_*``.  The actions must be sampled *inside* the callable so that
        gradients flow through the log-density of the sampled actions.
    param_filter:
        Optional predicate selecting which named parameters to track.
    """

    def __init__(
        self,
        module: nn.Module,
        log_prob_fn: Callable[..., Tensor],
        param_filter: Optional[Callable[[str], bool]] = None,
    ) -> None:
        self.module = module
        self.log_prob_fn = log_prob_fn
        self.param_filter = param_filter or (lambda name: True)
        self._fisher: Dict[str, Tensor] = {}
        self._num_batches = 0

    # ------------------------------------------------------------------
    def tracked_params(self) -> Dict[str, nn.Parameter]:
        return {
            name: p
            for name, p in self.module.named_parameters()
            if p.requires_grad and self.param_filter(name)
        }

    def __call__(self, *args, **kwargs) -> None:
        """Accumulate one batch of Fisher estimates."""

        self.update(*args, **kwargs)

    def update(self, batch_size_scale: int = 1, *args, **kwargs) -> None:
        params = self.tracked_params()
        if not self._fisher:
            self._fisher = _zero_like_params(params)

        self.module.zero_grad(set_to_none=True)
        log_prob = self.log_prob_fn(*args, **kwargs)
        # (1/N) sum_n (d log pi / d theta)^2 over the whole batch.
        if log_prob.dim() == 0:
            log_prob = log_prob.unsqueeze(0)
        loss = log_prob.mean()
        grads = torch.autograd.grad(loss, list(params.values()), retain_graph=False)
        for (name, _), grad in zip(params.items(), grads):
            if grad is None:
                continue
            self._fisher[name] += grad.detach() ** 2 * batch_size_scale
        self._num_batches += batch_size_scale

    # ------------------------------------------------------------------
    @property
    def num_batches(self) -> int:
        return self._num_batches

    def compute(self, normalize: bool = True) -> Dict[str, Tensor]:
        """Return the (optionally normalized) diagonal Fisher."""

        if not self._fisher:
            raise RuntimeError("No Fisher information accumulated yet.")
        if not normalize or self._num_batches == 0:
            return {k: v.clone() for k, v in self._fisher.items()}
        return {k: v / self._num_batches for k, v in self._fisher.items()}

    # ------------------------------------------------------------------
    @classmethod
    def estimate(
        cls,
        module: nn.Module,
        log_prob_fn: Callable[..., Tensor],
        batches: Iterable,
        num_batches: int = 10000,
        normalize: bool = True,
        progress: bool = False,
        param_filter: Optional[Callable[[str], bool]] = None,
    ) -> Dict[str, Tensor]:
        """Estimate the diagonal Fisher from ``num_batches`` batches.

        ``batches`` is any iterable yielding the positional/keyword arguments
        consumed by ``log_prob_fn``.  NetHack samples 10000 batches from NLD-AA.
        """

        estimator = cls(module, log_prob_fn, param_filter=param_filter)
        iterator = iter(batches)
        for _ in range(num_batches):
            try:
                batch = next(iterator)
            except StopIteration:
                iterator = iter(batches)
                batch = next(iterator)
            if isinstance(batch, dict):
                estimator.update(**batch)
            elif isinstance(batch, tuple):
                estimator.update(*batch)
            else:
                estimator.update(batch)
        if progress:
            print(f"[fisher] accumulated {estimator.num_batches} batches")
        return estimator.compute(normalize=normalize)

"""Coefficient schedules for the retention losses.

The NetHack kickstarting loss uses ``coefficient = 0.5`` scaled by an
exponential decay of ``0.99998`` applied every training step (Appendix B.1).
"""

from __future__ import annotations

import abc


class CoefficientSchedule(abc.ABC):
    def __init__(self, initial: float) -> None:
        self.initial = float(initial)

    @abc.abstractmethod
    def value(self, step: int) -> float:
        ...

    def __call__(self, step: int) -> float:
        return self.value(step)


class ConstantSchedule(CoefficientSchedule):
    """``value(step) == initial`` for every step (used by BC in NetHack)."""

    def value(self, step: int) -> float:  # noqa: D102
        return self.initial


class ExponentialDecaySchedule(CoefficientSchedule):
    """``value(step) = initial * decay ** step``.

    NetHack kickstarting uses ``decay=0.99998`` decayed once per training step.
    """

    def __init__(self, initial: float, decay: float) -> None:
        super().__init__(initial)
        self.decay = float(decay)

    def value(self, step: int) -> float:  # noqa: D102
        if self.decay >= 1.0:
            return self.initial
        return self.initial * (self.decay ** step)


def make_schedule(initial: float, decay: float = 1.0) -> CoefficientSchedule:
    if decay >= 1.0:
        return ConstantSchedule(initial)
    return ExponentialDecaySchedule(initial, decay)

"""Common interface for knowledge-retention methods."""

from __future__ import annotations

import abc
from dataclasses import dataclass, field
from typing import Any, Dict, Optional

import torch


@dataclass
class RetentionConfig:
    """Configuration shared by all knowledge-retention methods.

    Attributes
    ----------
    method:
        One of ``"none"``, ``"ewc"``, ``"bc"``, ``"ks"``, ``"em"``.
    coefficient:
        The multiplier applied to the auxiliary retention loss.  The paper uses
        2.0 for BC in NetHack, 0.5 for KS in NetHack (with exponential decay),
        2e6 for the EWC regularization coefficient in NetHack, 100 for the EWC
        actor regularization coefficient in Meta-World and 1 for BC in
        Meta-World (Table 3).
    decay:
        Exponential decay applied to ``coefficient`` every *training step*
        (NetHack uses 0.99998 for KS).  ``1.0`` means no decay.
    regularize_critic:
        The paper never regularizes the critic (Appendix C.5), so this defaults
        to ``False``.
    """

    method: str = "none"
    coefficient: float = 1.0
    decay: float = 1.0
    regularize_critic: bool = False
    extra: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        valid = {"none", "ewc", "bc", "ks", "em"}
        if self.method not in valid:
            raise ValueError(f"Unknown retention method {self.method!r}; expected one of {sorted(valid)}")


class RetentionMethod(abc.ABC):
    """Base class for knowledge-retention methods.

    A retention method exposes a single scalar ``aux_loss`` that is added to the
    reinforcement-learning objective::

        total_loss = rl_loss + coefficient * retention.aux_loss(...)

    and an optional ``on_train_step`` hook used for coefficient schedules.
    """

    def __init__(self, config: Optional[RetentionConfig] = None) -> None:
        self.config = config or RetentionConfig()
        self._step = 0

    # ------------------------------------------------------------------ API
    @abc.abstractmethod
    def aux_loss(self, *args: Any, **kwargs: Any) -> torch.Tensor:
        """Return the (un-scaled) auxiliary retention loss."""

    def on_train_step(self) -> None:
        """Advance any internal schedules by one training step."""

        self._step += 1

    @property
    def coefficient(self) -> float:
        return self.config.coefficient

    @property
    def step(self) -> int:
        return self._step

    # Convenience -------------------------------------------------------
    def state_dict(self) -> Dict[str, Any]:
        return {"step": self._step, "config": self.config.__dict__}

    def load_state_dict(self, state: Dict[str, Any]) -> None:
        self._step = state.get("step", 0)

    @staticmethod
    def build(config: RetentionConfig):
        """Factory returning the concrete method described by ``config``."""

        from .distillation import BehavioralCloning, Kickstarting
        from .episodic_memory import EpisodicMemory
        from .ewc import EWC

        if config.method == "none":
            return None
        if config.method == "ewc":
            return EWC(config)
        if config.method == "bc":
            return BehavioralCloning(config)
        if config.method == "ks":
            return Kickstarting(config)
        if config.method == "em":
            return EpisodicMemory(config)
        raise ValueError(f"Unknown retention method {config.method!r}")

"""Replay-based retention: episodic memory (EM).

At the beginning of fine-tuning a set of transitions from the pre-training task
is collected and inserted into the off-policy replay buffer.  That protected
region is never overwritten during training.  In the Meta-World experiments
10000 transitions are protected (10% of the 100k buffer, Appendix B.3) and in
Montezuma's Revenge a buffer of 500 trajectories gathered by the pre-trained
agent is used.

EM is only applicable to off-policy algorithms that maintain a replay buffer
(SAC), see Appendix C.3 -- on-policy APPO/PPO cannot use it trivially.
"""

from __future__ import annotations

from typing import Dict, Optional, Tuple

import numpy as np
import torch
from torch import Tensor

from .base import RetentionConfig, RetentionMethod


class ProtectedReplayBuffer:
    """A replay buffer with a protected region reserved for old (pre-training) data.

    The first ``protected_size`` slots are reserved for the pre-training
    transitions and are never overwritten.  New transitions are stored in the
    remaining ``capacity - protected_size`` slots with a circular pointer.
    """

    def __init__(self, capacity: int, protected_size: int = 0, seed: Optional[int] = None) -> None:
        if protected_size > capacity:
            raise ValueError("protected_size cannot exceed capacity")
        self.capacity = int(capacity)
        self.protected_size = int(protected_size)
        self._rng = np.random.default_rng(seed)
        self._size = 0            # total filled slots
        self._ptr = self.protected_size  # circular pointer over the non-protected region
        self._storage: Dict[str, np.ndarray] = {}

    # ------------------------------------------------------------------
    def _ensure(self, sample: Dict[str, np.ndarray]) -> None:
        if self._storage:
            return
        for key, value in sample.items():
            value = np.asarray(value)
            shape = (self.capacity,) + value.shape
            dtype = np.float32 if np.issubdtype(value.dtype, np.floating) else value.dtype
            self._storage[key] = np.zeros(shape, dtype=dtype)

    @property
    def num_protected(self) -> int:
        return min(self._size, self.protected_size)

    @property
    def size(self) -> int:
        return self._size

    def __len__(self) -> int:  # pragma: no cover - trivial
        return self._size

    # ------------------------------------------------------------------
    def add_protected(self, transitions: Dict[str, np.ndarray]) -> None:
        """Insert the pre-training transitions into the protected region."""

        self._ensure(transitions)
        n = len(next(iter(transitions.values())))
        n = min(n, self.protected_size)
        for key in self._storage:
            self._storage[key][:n] = np.asarray(transitions[key])[:n]
        self._size = max(self._size, n)
        self._ptr = max(self._ptr, n)

    def add(self, transition: Dict[str, np.ndarray]) -> None:
        """Insert a single new transition (never touches the protected region)."""

        self._ensure(transition)
        idx = self._ptr
        for key in self._storage:
            self._storage[key][idx] = np.asarray(transition[key])
        self._ptr = self.protected_size + (self._ptr - self.protected_size + 1) % max(
            self.capacity - self.protected_size, 1
        )
        self._size = min(self._size + 1, self.capacity)

    def add_batch(self, transitions: Dict[str, np.ndarray]) -> None:
        n = len(next(iter(transitions.values())))
        for i in range(n):
            self.add({k: v[i] for k, v in transitions.items()})

    # ------------------------------------------------------------------
    def sample(self, batch_size: int) -> Dict[str, Tensor]:
        idx = self._rng.integers(0, self._size, size=batch_size)
        return {
            key: torch.as_tensor(value[idx]).float() if value.dtype.kind == "f"
            else torch.as_tensor(value[idx])
            for key, value in self._storage.items()
        }

    def state_dict(self) -> Dict[str, object]:
        return {
            "capacity": self.capacity,
            "protected_size": self.protected_size,
            "size": self._size,
            "ptr": self._ptr,
        }


class EpisodicMemory(RetentionMethod):
    """Thin :class:`RetentionMethod` wrapper around :class:`ProtectedReplayBuffer`.

    Episodic memory does not add an explicit auxiliary loss -- it is implemented
    by protecting part of the replay buffer.  ``aux_loss`` therefore returns a
    zero tensor and the actual logic lives in ``buffer``.
    """

    def __init__(self, config: Optional[RetentionConfig] = None, buffer: Optional[ProtectedReplayBuffer] = None) -> None:
        super().__init__(config)
        self.buffer = buffer

    def attach_buffer(self, buffer: ProtectedReplayBuffer) -> None:
        self.buffer = buffer

    def fill(self, transitions: Dict[str, np.ndarray]) -> None:
        if self.buffer is None:
            raise RuntimeError("EpisodicMemory has no buffer attached.")
        self.buffer.add_protected(transitions)

    def aux_loss(self, *_, **__) -> Tensor:
        return torch.zeros(())

"""Actor-critic network for Montezuma's Revenge (Appendix B.2)."""

from __future__ import annotations

import numpy as np
import torch
import torch.nn as nn
from torch import Tensor
from torch.distributions import Categorical


def orthogonal_init(module: nn.Module, gain: float = float(np.sqrt(2))) -> None:
    if isinstance(module, (nn.Conv2d, nn.Linear)):
        nn.init.orthogonal_(module.weight, gain=gain)
        if module.bias is not None:
            nn.init.zeros_(module.bias)


class AtariActorCritic(nn.Module):
    """Shared CNN trunk with a policy head and a value head."""

    def __init__(self, num_actions: int = 18, hidden_dim: int = 512) -> None:
        super().__init__()
        self.num_actions = num_actions
        self.trunk = nn.Sequential(
            nn.Conv2d(4, 32, 8, stride=4), nn.LeakyReLU(),
            nn.Conv2d(32, 64, 4, stride=2), nn.LeakyReLU(),
            nn.Conv2d(64, 64, 3, stride=1), nn.LeakyReLU(),
            nn.Flatten(),
        )
        with torch.no_grad():
            n_flatten = self.trunk(torch.zeros(1, 4, 84, 84)).shape[1]
        self.fc = nn.Sequential(nn.Linear(n_flatten, hidden_dim), nn.ReLU())
        self.policy_head = nn.Linear(hidden_dim, num_actions)
        self.value_head = nn.Linear(hidden_dim, 1)
        self.apply(orthogonal_init)
        nn.init.orthogonal_(self.policy_head.weight, gain=0.01)
        nn.init.orthogonal_(self.value_head.weight, gain=1.0)

    # ------------------------------------------------------------------
    def features(self, obs: Tensor) -> Tensor:
        return self.fc(self.trunk(obs))

    def forward(self, obs: Tensor) -> tuple[Tensor, Tensor]:
        h = self.features(obs)
        return self.policy_head(h), self.value_head(h)

    def distribution(self, obs: Tensor) -> Categorical:
        logits, _ = self.forward(obs)
        return Categorical(logits=logits)

    def act(self, obs: Tensor) -> Tensor:
        return self.distribution(obs).sample()

    def evaluate_actions(self, obs: Tensor, actions: Tensor):
        logits, values = self.forward(obs)
        dist = Categorical(logits=logits)
        return dist.log_prob(actions), dist.entropy(), values.squeeze(-1)


class RandomPolicy:
    """Uniform-random policy used in smoke tests and as a fallback."""

    def __init__(self, num_actions: int = 18) -> None:
        self.num_actions = num_actions

    def act(self, obs: Tensor) -> Tensor:
        return torch.randint(0, self.num_actions, (obs.shape[0],), device=obs.device)

"""Centered Kernel Alignment (Kornblith et al., 2019).

Appendix B.3::

    CKA(K, L) = HSIC(K, L) / sqrt(HSIC(K, K) * HSIC(L, L))

with a linear kernel in both cases.  We use it to measure how the activations of
the actor and critic change during fine-tuning (Figure 20).
"""

from __future__ import annotations

from typing import Callable, Dict, List, Optional, Sequence

import numpy as np
import torch
from torch import Tensor


def _center(k: Tensor) -> Tensor:
    n = k.shape[0]
    identity = torch.eye(n, device=k.device, dtype=k.dtype)
    ones = torch.ones(n, n, device=k.device, dtype=k.dtype)
    return k - ones @ k / n - k @ ones / n + (ones @ k @ ones) / (n * n)


def linear_kernel(x: Tensor) -> Tensor:
    return x @ x.t()


def hsic(k: Tensor, l: Tensor) -> Tensor:
    """Hilbert-Schmidt Independence Criterion with centred kernels."""

    return (_center(k) * _center(l)).sum() / (k.shape[0] - 1) ** 2


def cka(x: Tensor, y: Tensor, kernel: Callable[[Tensor], Tensor] = linear_kernel) -> float:
    """CKA between two activation matrices ``x`` and ``y`` of shape ``(n, p)``."""

    k, l = kernel(x), kernel(y)
    denom = torch.sqrt(hsic(k, k) * hsic(l, l))
    if float(denom) == 0.0:
        return float("nan")
    return float((hsic(k, l) / denom).item())


def layer_activations(model, inputs: Tensor, layer_names: Optional[Sequence[str]] = None) -> Dict[str, Tensor]:
    """Collect the activations of the named layers for a batch of ``inputs``."""

    activations: Dict[str, Tensor] = {}
    hooks = []

    def make_hook(name: str):
        def hook(_module, _inputs, output):
            activation = output[0] if isinstance(output, tuple) else output
            activations[name] = activation.detach()
        return hook

    for name, module in model.named_modules():
        if not name:
            continue
        if layer_names is None or name in layer_names:
            hooks.append(module.register_forward_hook(make_hook(name)))
    model(inputs)
    for hook in hooks:
        hook.remove()
    return activations


def cka_over_training(
    reference_activations: Dict[str, Tensor],
    current_activations: Dict[str, Tensor],
) -> Dict[str, float]:
    """CKA between the pre-training activations and the current activations."""

    out: Dict[str, float] = {}
    for name, ref in reference_activations.items():
        cur = current_activations.get(name)
        if cur is None:
            continue
        out[name] = cka(ref.float(), cur.float())
    return out

"""NetHack Learning Environment wrappers.

The NLE observation used by the model has four components (Appendix B.1):

* ``glyphs`` -- the main dungeon screen encoded as character ids,
* ``colors`` -- the per-cell colour ids,
* ``blstats`` -- the player status vector (health, hunger, ...),
* ``message`` -- the textual message line.

The environment is rolled out until the agent dies, 150 steps pass without
progress, or 100k steps are taken (addendum).
"""

from __future__ import annotations

from typing import Dict, Optional, Tuple

import numpy as np

from .config import NetHackConfig


def _require_nle():
    try:
        import nle  # noqa: F401
    except Exception as exc:  # pragma: no cover - optional dependency
        raise ImportError(
            "NetHack requires the NLE package: pip install nle "
            "(see https://github.com/heiner/nle)."
        ) from exc


class NetHackEnv:
    """Thin wrapper around ``nle.env.NLE`` exposing the model's observation dict."""

    def __init__(self, config: NetHackConfig, seed: int = 0, character: Optional[str] = None) -> None:
        _require_nle()
        import gymnasium as gym

        self.config = config
        self.character = character or config.character
        self.env = gym.make(
            "NetHackScore-v0",
            observation_keys=("glyphs", "colors", "blstats", "message"),
            actions=None,
            character=self.character,
            max_episode_steps=100_000,
            no_progress_timeout=150,
        )
        self.env.reset(seed=seed)

    # ------------------------------------------------------------------
    def _obs(self, raw: Dict[str, np.ndarray]) -> Dict[str, np.ndarray]:
        return {
            "glyphs": np.asarray(raw["glyphs"]).astype(np.int64),
            "colors": np.asarray(raw["colors"]).astype(np.int64),
            "blstats": np.asarray(raw["blstats"]).astype(np.float32),
            "message": np.asarray(raw["message"]).astype(np.int64),
        }

    def reset(self) -> Dict[str, np.ndarray]:
        raw, _ = self.env.reset()
        return self._obs(raw)

    def step(self, action: int) -> Tuple[Dict[str, np.ndarray], float, bool, Dict]:
        raw, reward, terminated, truncated, info = self.env.step(action)
        return self._obs(raw), float(reward), bool(terminated or truncated), info

    def render_ascii(self) -> str:
        return "".join(chr(c) for c in np.asarray(self.env.unwrapped.tty_chars).flatten().tolist())

    def close(self) -> None:
        self.env.close()


def make_env_factory(config: NetHackConfig):
    """Return a factory ``seed -> NetHackEnv`` for the APPO rollout workers."""

    def factory(seed: int) -> NetHackEnv:
        return NetHackEnv(config, seed=seed)

    return factory

